<?php echo form_open(get_uri('warehouses/transfers/'.$transfer->id.'/receive'),['id'=>'transfer-receive-form']);echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title">Recibir <?php echo esc($transfer->folio); ?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><table class="table"><thead><tr><th>Producto</th><th>Enviado</th><th>Recibido acumulado</th><th>Recibir ahora</th><th>Pendiente</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?php echo esc($l->internal_code.' - '.$l->product_name); ?></td><td><?php echo esc(to_decimal_format($l->quantity_sent)); ?></td><td><?php echo esc(to_decimal_format($l->received)); ?></td><td><input class="form-control" inputmode="decimal" name="quantities[<?php echo $l->id; ?>]" value="<?php echo esc($l->pending); ?>"></td><td><?php echo esc(to_decimal_format($l->pending)); ?></td></tr><?php endforeach; ?></tbody></table><label>Observaciones de recepción</label><textarea class="form-control" name="notes"></textarea><div class="alert alert-info mt10">Puede recibir parcialmente. Nunca se permitirá recibir más de lo enviado.</div></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Registrar recepción</button></div><?php echo form_close(); ?><script>$('#transfer-receive-form').appForm({onSuccess:function(){location.reload();}});</script>
